style.css:
body {
  background-image: url("https://www.roblox.com/es/home");
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  height: 100vh;
  margin: 0;
  position: relative;
  overflow: hidden;
}

body::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.4); /* oscurece la imagen */
  backdrop-filter: blur(6px); /* desenfoque del fondo */
  -webkit-backdrop-filter: blur(6px);
  z-index: 0;
}

* {
  position: relative;
  z-index: 1; /* asegura que el contenido esté por encima del blur */
}
